// SRI hashes (sha384) of the vendor/ files, generated by scripts/vendor.mjs into vendor/integrity.json.
// Used when loading scripts lazily: s.integrity = await integridad('jspdf.umd.min.js').
// Tolerant: if the JSON is unavailable (tests, offline without cache) it returns undefined and the script loads without SRI.
let promesa = null;

export function cargarIntegridades() {
  promesa ||= (async () => {
    try {
      const r = await fetch(new URL('../../vendor/integrity.json', import.meta.url).href);
      return r.ok ? await r.json() : {};
    } catch (e) {
      return {};
    }
  })();
  return promesa;
}

export async function integridad(nombre) {
  const m = await cargarIntegridades();
  return m && typeof m[nombre] === 'string' && /^sha384-[A-Za-z0-9+/=]+$/.test(m[nombre]) ? m[nombre] : undefined;
}
